local Animation_In = "CommonScreenBlackFadeIn"
local Animation_Idle = "CommonScreenBlackFadeIdle"
local Animation_Out = "CommonScreenBlackFadeOut"
local Animation_In_White = "CommonScreenWhiteFadeIn"
local Animation_Out_White = "CommonScreenWhiteFadeOut"
local Color = {
    Black = "000000",
    White = "FFFFFF",
}
------------ define ------------

---@class CommonScreenBlack
---@field Black                          UnityEngine.UI.Image
