function CommonScreenBlack:GetAnimationTime(animationName)
    local clips = self.Animator.runtimeAnimatorController.animationClips
    for i = 1, clips.Length do
        local curAnimation = clips[i - 1]
        if curAnimation.name == animationName then
            return curAnimation.length
        end
    end
end

---ShowSequence
---@param isShowIn boolean
---@param isShowOut boolean
---@param idleDuring number
---@param callBack fun():void
---@param color string
function CommonScreenBlack:ShowSequence(isShowIn, isShowOut, idleDuring, callBack, color)
    local colorBG = color or Color.Black
    self.Black.color = CS.Engine.Lib.XLuaUtils.HexToColor(string.format("#%s", colorBG))
    local animationIn = color == Color.White and Animation_In_White or Animation_In
    local animationOut = color == Color.White and Animation_Out_White or Animation_Out
    local animationInLength = self:GetAnimationTime(animationIn) 
    local animationOutLength = self:GetAnimationTime(animationOut)
    if isShowIn then
        self:PlayPanelAnimation(animationIn, animationInLength)
    end
    if idleDuring and idleDuring > 0 then
        self:PlayPanelAnimation(Animation_Idle, idleDuring)
    end
    if isShowOut then
        self:PlayPanelAnimation(animationOut, animationOutLength)
    end
    if callBack then
        callBack()
    end
    KTool.SafeDelete(self.controller.gameObject)
end

---PlayPanelAnimation
---@param animationName string 动画名
---@param pDuring number 等待动画表现时间
function CommonScreenBlack:PlayPanelAnimation(animationName, pDuring)
    if not isNull(self.Animator) then
        self.Animator.enabled = true
        self.Animator:Play(animationName)
        cs_coroutine.yield_return(Yielders.GetWaitForSeconds(pDuring))
        self.Animator.enabled = false
    end
end

